@Component({
  selector: 'app-selector-estado',
  template: `
    @for (e of estados; track e) {
      <button [class.activo]="estado() === e" (click)="estado.set(e)">{{ e }}</button>
    }
  `,
})
export class SelectorEstado {
  readonly estado = model<'pendiente' | 'en-curso' | 'hecha'>('pendiente');
  readonly estados = ['pendiente', 'en-curso', 'hecha'] as const;
}

